operations.document:
mutation AddTodo($input: AddTodoInput!) {
  addTodo(input: $input) {
    id
    title
  }
}

query Todo($id: ID!) {
  todo(id: $id) {
    id
    title
    done
    status
    owner {
      name
      email
    }
  }
}

mutation ToggleTodo($id: ID!) {
  toggleTodo(id: $id) {
    id
    done
    status
  }
}

query Todos($status: TodoStatus) {
  todos(status: $status) {
    id
    title
    done
  }
}

query Users {
  users {
    id
    name
    email
  }
}

